ALTER TABLE product_command_admission DROP CONSTRAINT product_command_admission_command_kind_check;
ALTER TABLE product_command_admission ADD CONSTRAINT product_command_admission_command_kind_check CHECK (command_kind IN ('CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'WITHDRAW_FACTOR_PROPOSAL', 'CREATE_FACTOR_STUDY_GRANT', 'STAGE_FACTOR_STUDY', 'WITHDRAW_FACTOR_STUDY', 'PREPARE_FACTOR_RESEARCH', 'CANCEL_FACTOR_RESEARCH_PREPARATION', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_command_kind_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_command_kind_check CHECK (command_kind IN ('CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'WITHDRAW_FACTOR_PROPOSAL', 'CREATE_FACTOR_STUDY_GRANT', 'STAGE_FACTOR_STUDY', 'WITHDRAW_FACTOR_STUDY', 'PREPARE_FACTOR_RESEARCH', 'CANCEL_FACTOR_RESEARCH_PREPARATION', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_kind_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_kind_check CHECK (outcome_kind IN ('RESEARCH_RUN', 'STRATEGY', 'STRATEGY_PROMOTION', 'BACKTEST_RUN', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION', 'INTEGRATION_REVISION', 'CHART_CALCULATION_OPERATION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING', 'FACTOR_CHAT_EVENT', 'FACTOR_PROPOSAL_OPERATION', 'FACTOR_STUDY_OPERATION', 'RESEARCH_PREPARATION_OPERATION'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_id_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_id_check CHECK (
    (outcome_kind IN ('RESEARCH_RUN', 'BACKTEST_RUN', 'INTEGRATION', 'CHART_CALCULATION_OPERATION')
        AND outcome_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    OR (outcome_kind IN ('STRATEGY', 'STRATEGY_PROMOTION', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION_REVISION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING', 'FACTOR_CHAT_EVENT', 'FACTOR_PROPOSAL_OPERATION', 'FACTOR_STUDY_OPERATION', 'RESEARCH_PREPARATION_OPERATION')
        AND outcome_id ~ '^[0-9a-f]{64}$')
);


-- Original accepted Human preparation command, never a second Research Run or queue identity.
CREATE TABLE research_preparation (
 command_id UUID PRIMARY KEY REFERENCES product_command_receipt DEFERRABLE INITIALLY DEFERRED,
 owner TEXT NOT NULL CHECK(length(owner)>0),
 accepted_fingerprint TEXT UNIQUE NOT NULL CHECK(accepted_fingerprint ~ '^[0-9a-f]{64}$'),
 accepted_payload TEXT NOT NULL,
 revision BIGINT NOT NULL CHECK(revision>=0),
 state TEXT NOT NULL CHECK(state IN ('ACCEPTED','RUNNING','INPUT_PENDING','READY','BLOCKED','UNKNOWN','CANCEL_REQUESTED','CANCELLED')),
 phase TEXT NOT NULL CHECK(phase ~ '^[A-Z_]+$'),
 outputs_payload TEXT NOT NULL,
 detail_payload TEXT NOT NULL
);
CREATE FUNCTION research_preparation_preserve_intent() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.command_id IS DISTINCT FROM OLD.command_id OR NEW.owner IS DISTINCT FROM OLD.owner
 OR NEW.accepted_fingerprint IS DISTINCT FROM OLD.accepted_fingerprint OR NEW.accepted_payload IS DISTINCT FROM OLD.accepted_payload
 OR NEW.revision <> OLD.revision+1 THEN RAISE EXCEPTION 'Research preparation requires immutable intent and exact successor'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(OLD.outputs_payload::jsonb) old_fact WHERE (NEW.outputs_payload::jsonb->old_fact.key) IS DISTINCT FROM old_fact.value) THEN RAISE EXCEPTION 'Research preparation retained outputs are immutable'; END IF;
 IF NOT (
 (OLD.state='ACCEPTED' AND NEW.state IN ('RUNNING','CANCELLED','BLOCKED')) OR
 (OLD.state='RUNNING' AND NEW.state IN ('RUNNING','INPUT_PENDING','READY','BLOCKED','UNKNOWN','CANCEL_REQUESTED')) OR
 (OLD.state IN ('INPUT_PENDING','BLOCKED') AND NEW.state IN ('RUNNING','CANCELLED')) OR
 (OLD.state='UNKNOWN' AND NEW.state IN ('RUNNING','CANCEL_REQUESTED')) OR
 (OLD.state='CANCEL_REQUESTED' AND NEW.state IN ('UNKNOWN','CANCEL_REQUESTED')) OR
 (OLD.state IN ('UNKNOWN','CANCEL_REQUESTED') AND NEW.state='CANCELLED' AND NEW.phase='OWNER_DRAINED' AND NEW.outputs_payload::jsonb ? 'cancellation') OR
 (OLD.state='READY' AND NEW.state='RUNNING' AND NEW.phase='CONFIRMING') OR
 (OLD.state='READY' AND NEW.state='CANCELLED' AND NEW.phase='CANCELLATION')
 ) THEN RAISE EXCEPTION 'Illegal Research preparation transition'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER research_preparation_intent_immutable BEFORE UPDATE ON research_preparation FOR EACH ROW EXECUTE FUNCTION research_preparation_preserve_intent();
CREATE TRIGGER research_preparation_no_delete BEFORE DELETE OR TRUNCATE ON research_preparation FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
CREATE UNIQUE INDEX research_preparation_future_research_command ON research_preparation (((accepted_payload::jsonb->'input'->>'research_command_id')::uuid));
